<?php $page_title='New Appointment';require_once __DIR__.'/../includes/header.php';$patients=$pdo->query("SELECT id,name,patient_code FROM patients ORDER BY name")->fetchAll();$doctors=$pdo->query("SELECT id,name,specialization FROM doctors WHERE status='active' ORDER BY name")->fetchAll();$pid=(int)($_GET['patient_id']??0);if($_SERVER['REQUEST_METHOD']==='POST'){$pdo->prepare("INSERT INTO appointments(patient_id,doctor_id,appointment_date,appointment_time,reason,status) VALUES(?,?,?,?,?,?)")->execute([$_POST['patient_id'],$_POST['doctor_id'],$_POST['appointment_date'],$_POST['appointment_time'],$_POST['reason'],'scheduled']);header('Location:index.php');exit;}?><h2>New Appointment</h2><div class="card p-4 mt-3"><form method="post"><div class="row g-3"><div class="col-md-6"><label>Patient</label><select name="patient_id" class="form-select" required><?php foreach($patients as $p):?><option value="<?=$p['id']?>" <?=$pid==$p['id']?'selected':''?>><?=e($p['name'])?> (<?=$p['patient_code']?>)</option><?php endforeach;?></select></div><div class="col-md-6"><label>Doctor</label><select name="doctor_id" class="form-select" required><?php foreach($doctors as $d):?><option value="<?=$d['id']?>">Dr. <?=e($d['name'])?> — <?=e($d['specialization'])?></option><?php endforeach;?></select></div><div class="col-md-6"><label>Date</label><input type="date" name="appointment_date" value="<?=date('Y-m-d')?>" class="form-control" required></div><div class="col-md-6"><label>Time</label><input type="time" name="appointment_time" value="09:00" class="form-control" required></div><div class="col-12"><label>Reason</label><textarea name="reason" class="form-control" required></textarea></div></div><button class="btn btn-primary mt-3">Book Appointment</button></form></div><?php require_once __DIR__.'/../includes/footer.php';?>